def is_majority(arr, n, elem):
    # Binary search to find the first occurrence of elem
    low, high = 0, n - 1
    first = n
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] >= elem:
            high = mid - 1
        else:
            low = mid + 1
    first = low

    # Check if elem exists and occurs more than n/2 times
    # If it appears > n/2 times, it must occupy index `first + n // 2`
    if first < n and arr[first] == elem:
        if first + n // 2 < n and arr[first + n // 2] == elem:
            return True
    return False

assert is_majority([1, 2, 3, 3, 3, 3, 10], 7, 3) == True
