def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False
    if any(len(row) != n for row in matrix):
        return False

    nums = set()
    for row in matrix:
        for x in row:
            nums.add(x)
    if nums != set(range(1, n * n + 1)):
        return False

    target = n * (n * n + 1) // 2

    if any(sum(row) != target for row in matrix):
        return False
    if any(sum(matrix[r][c] for r in range(n)) != target for c in range(n)):
        return False

    d1 = sum(matrix[i][i] for i in range(n))
    d2 = sum(matrix[i][n - 1 - i] for i in range(n))

    return d1 == target and d2 == target
