class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counts = {}
        n = len(nums)

        # Iterate through all subarrays of size k
        # There are n - k + 1 such subarrays
        for i in range(n - k + 1):
            # Extract the current subarray
            subarray = nums[i : i + k]
            # Identify unique numbers in this subarray.
            # A number appearing multiple times in the same subarray 
            # still counts as appearing in that subarray only once.
            unique_nums = set(subarray)

            # Increment the count for each unique number found in this subarray
            for num in unique_nums:
                counts[num] = counts.get(num, 0) + 1

        max_val = -1
        # Iterate through the counts to find numbers that appear in exactly one subarray
        for num, count in counts.items():
            if count == 1:
                if num > max_val:
                    max_val = num

        return max_val
