def is_samepatterns(patterns, words):
    if len(patterns) != len(words):
        return False

    p_to_w = {}
    w_to_p = {}

    for p, w in zip(patterns, words):
        if p in p_to_w and p_to_w[p] != w:
            return False
        if w in w_to_p and w_to_p[w] != p:
            return False
        p_to_w[p] = w
        w_to_p[w] = p

    return True

